// Pings IndexNow (Bing, Yandex, Seznam, Naver) with only the URLs that were
// added, changed or removed since the previous production deploy.
//
// Runs from .github/workflows/indexnow.yml after each successful production
// deploy. The previous sitemap snapshot is kept as an Actions artifact and
// passed in with --prev; --since is the fallback when there is none. Files
// changed in the deploy's commit range (--from) are mapped to URLs with ROUTES
// and unioned in, because lastmod.json is regenerated by hand and can lag.
//
// Ownership is proven by public/<KEY>.txt being reachable at the site root.
//
//   node scripts/indexnow.mjs --prev prev.json --out next.json --from <sha>
//   node scripts/indexnow.mjs --dry-run / /sitemap   # explicit paths
//   node scripts/indexnow.mjs --help

import { execFileSync } from 'node:child_process';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

// SITE block
const HOST = 'www.vietnamlaunchpad.com';
const KEY = '01b92c45207153fe';
const SITEMAP = 'https://www.vietnamlaunchpad.com/sitemap.xml';
// lastmod comes from git history (or the committed snapshot on a shallow
// clone), never a build-time stamp, so every lastmod change is meaningful.
const IGNORE_LASTMOD = [];
const PAGES = { router: 'next-app', dir: 'src/app' };
// Changed repo files -> route patterns. Components, layouts and styles map to
// nothing on purpose: a template change is not a content change.
// Pages outside the sitemap (noindex or HTML-only) are left out so a deleted
// one is not mistaken for a removed URL.
const APP_EXCLUDED = /^src\/app\/\(site\)\/(?:\[locale\]\/)?(?:api|enterprise|get-started)(?:\/|$)/;
// URLs carry no locale segment (localePrefix 'never'), so drop [locale].
const localeFree = (route) => (route === '/[locale]' ? '/' : route.replace(/^\/\[locale\]/, ''));
export const ROUTES = [
  {
    file: /^src\/app\/.+/,
    to: (m) => {
      if (APP_EXCLUDED.test(m[0])) return [];
      const route = fileRoute(m[0], PAGES);
      return route ? [localeFree(route)] : [];
    },
  },
  // Data sources read by the dynamic routes (generateStaticParams) and the listings.
  { file: /^src\/data\/services\.ts$/, to: ['/services', '/services/[slug]'] },
  { file: /^src\/data\/(?:guides|guidesSeo|bestEsimGuide)\.ts$/, to: ['/guides', '/guides/[slug]'] },
  { file: /^src\/data\/blog\.ts$/, to: ['/blog', '/blog/[slug]'] },
  { file: /^src\/data\/visas\.ts$/, to: ['/visa', '/visa/[country]'] },
  { file: /^src\/data\/(?:visaCurated|visa-copy)\.ts$/, to: '/visa/[country]' },
  { file: /^src\/data\/taxTreaties\.ts$/, to: ['/tax-treaty', '/tax-treaty/[country]'] },
  { file: /^src\/data\/salaryRoles\.ts$/, to: ['/salary', '/salary/[role]'] },
  { file: /^src\/data\/homeCopy\.ts$/, to: ['/', '/visa', '/about'] },
  { file: /^src\/data\/aboutCopy\.ts$/, to: '/about' },
];

const ENDPOINT = 'https://api.indexnow.org/indexnow';
const BATCH_SIZE = 10000;
const CHECK_CONCURRENCY = 6;
const CHECK_TIMEOUT_MS = 15000;
const BULK_MIN = 50;
const BULK_RATIO = 0.5;

const USAGE = `Usage: node scripts/indexnow.mjs [options] [paths or URLs...]

Pings IndexNow with the URLs added, changed or removed since the previous
sitemap snapshot. With explicit paths, sends exactly those instead.

Options:
  --host <h>        Override host (default ${HOST})
  --key <k>         Override IndexNow key
  --sitemap <url>   Override sitemap URL (index or urlset)
  --prev <file>     Previous snapshot JSON (missing file is fine)
  --out <file>      Write the current snapshot JSON here
  --since <ISO>     Without a usable --prev, count URLs with lastmod after this
  --from <sha>      Also map files changed in <sha>..<to> to URLs (ROUTES)
  --to <sha>        End of the commit range (default HEAD)
  --dry-run        Do everything except the POST
  --no-check        Skip the per-URL status, noindex and canonical checks
                    (robots.txt disallow rules always apply)
  --allow-bulk      Disable the whole-site change guard
  --help            Show this help`;

// ---------- pure helpers (exported for tests) ----------

const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };

export function decodeXml(s) {
  return s
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&(#x[0-9a-f]+|#[0-9]+|[a-z]+);/gi, (m, e) => {
      if (e[0] === '#') {
        const code = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
        return Number.isFinite(code) ? String.fromCodePoint(code) : m;
      }
      return ENTITIES[e.toLowerCase()] ?? m;
    })
    .trim();
}

function tagText(block, tag) {
  const m = block.match(new RegExp(`<(?:[\\w-]+:)?${tag}\\b[^>]*>([\\s\\S]*?)</(?:[\\w-]+:)?${tag}>`, 'i'));
  return m ? decodeXml(m[1]) : '';
}

function hostOf(url) {
  try {
    return new URL(url).host.toLowerCase();
  } catch {
    return '';
  }
}

// Returns { sitemaps: [child sitemap URLs], urls: { loc: lastmod } }.
// Only <url> locs on `host` are kept; child sitemaps are returned as found.
export function parseSitemap(xml, host) {
  const sitemaps = [];
  for (const m of xml.matchAll(/<(?:[\w-]+:)?sitemap\b[^>]*>([\s\S]*?)<\/(?:[\w-]+:)?sitemap>/gi)) {
    const loc = tagText(m[1], 'loc');
    if (loc) sitemaps.push(loc);
  }
  const urls = {};
  const want = host.toLowerCase();
  for (const m of xml.matchAll(/<(?:[\w-]+:)?url\b[^>]*>([\s\S]*?)<\/(?:[\w-]+:)?url>/gi)) {
    const loc = tagText(m[1], 'loc');
    if (!loc || hostOf(loc) !== want) continue;
    urls[loc] = tagText(m[1], 'lastmod');
  }
  return { sitemaps, urls };
}

function pathOf(url) {
  try {
    return new URL(url).pathname;
  } catch {
    return url;
  }
}

// prev and curr are { url: lastmod } maps.
export function diffSnapshots(prev, curr, ignoreLastmod = []) {
  const added = [];
  const changed = [];
  const removed = [];
  for (const [url, lastmod] of Object.entries(curr)) {
    if (!(url in prev)) {
      added.push(url);
      continue;
    }
    const before = prev[url];
    if (!lastmod || !before || lastmod === before) continue;
    const path = pathOf(url);
    if (ignoreLastmod.some((re) => re.test(path))) continue;
    changed.push(url);
  }
  for (const url of Object.keys(prev)) if (!(url in curr)) removed.push(url);
  return { added, changed, removed };
}

// URLs whose lastmod is strictly later than `since`. No lastmod, not counted.
export function changedSince(curr, since, ignoreLastmod = []) {
  const t = Date.parse(since);
  if (Number.isNaN(t)) return [];
  return Object.entries(curr)
    .filter(([url, lastmod]) => lastmod && Date.parse(lastmod) > t && !ignoreLastmod.some((re) => re.test(pathOf(url))))
    .map(([url]) => url);
}

// True when the change looks like a whole-site change and should not be sent.
export function bulkGuard(changeCount, currentCount) {
  return changeCount > BULK_MIN && changeCount > currentCount * BULK_RATIO;
}

function parseAttrs(tag) {
  const attrs = {};
  for (const m of tag.matchAll(/([\w:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))/g)) {
    attrs[m[1].toLowerCase()] = m[2] ?? m[3] ?? m[4] ?? '';
  }
  return attrs;
}

// "none" is shorthand for "noindex, nofollow", so it counts too.
const NOINDEX_RE = /(^|[\s,:;])(noindex|none)([\s,;]|$)/i;
const ROBOT_NAMES = new Set(['robots', 'googlebot', 'bingbot']);

export function isNoindex(xRobotsTag, html) {
  if (xRobotsTag && NOINDEX_RE.test(xRobotsTag)) return true;
  if (!html) return false;
  for (const m of html.matchAll(/<meta\b[^>]*>/gi)) {
    const a = parseAttrs(m[0]);
    if (a.name && ROBOT_NAMES.has(a.name.toLowerCase()) && NOINDEX_RE.test(a.content ?? '')) return true;
  }
  return false;
}

// rel=canonical from a Link header or an HTML <link> tag, resolved against the
// page URL. Returns null when the page declares none.
export function canonicalOf(linkHeader, html, base) {
  if (linkHeader) {
    for (const part of linkHeader.split(/,(?=\s*<)/)) {
      const m = part.match(/^\s*<([^>]*)>(.*)$/);
      if (!m) continue;
      const rel = m[2].match(/;\s*rel\s*=\s*(?:"([^"]*)"|([^\s;,]+))/i);
      if (rel && (rel[1] ?? rel[2]).toLowerCase().split(/\s+/).includes('canonical')) return new URL(m[1], base).href;
    }
  }
  if (html) {
    for (const m of html.matchAll(/<link\b[^>]*>/gi)) {
      const a = parseAttrs(m[0]);
      if (a.rel && a.href && a.rel.toLowerCase().split(/\s+/).includes('canonical')) {
        return new URL(decodeXml(a.href), base).href;
      }
    }
  }
  return null;
}

// Exact URL comparison after URL normalisation (host case, default port), fragment ignored.
export function sameUrl(a, b) {
  const x = new URL(a);
  const y = new URL(b);
  x.hash = '';
  y.hash = '';
  return x.href === y.href;
}

// robots.txt rules from every group naming one of `agents` ('*' by default).
// Returns [{ allow, pattern }] with empty Disallow lines skipped (they allow all).
export function parseRobots(text, agents = ['*']) {
  const want = agents.map((a) => a.toLowerCase());
  const rules = [];
  let groupAgents = [];
  let inRules = false;
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.replace(/#.*/, '').trim();
    const m = line.match(/^([a-z-]+)\s*:\s*(.*)$/i);
    if (!m) continue;
    const field = m[1].toLowerCase();
    const value = m[2].trim();
    if (field === 'user-agent') {
      if (inRules) {
        groupAgents = [];
        inRules = false;
      }
      groupAgents.push(value.toLowerCase());
    } else if (field === 'allow' || field === 'disallow') {
      inRules = true;
      if (value && groupAgents.some((a) => want.includes(a))) rules.push({ allow: field === 'allow', pattern: value });
    }
  }
  return rules;
}

function robotsRegExp(pattern) {
  const anchored = pattern.endsWith('$');
  const body = (anchored ? pattern.slice(0, -1) : pattern)
    .split('*')
    .map((s) => s.replace(/[.+?^${}()|[\]\\]/g, '\\$&'))
    .join('.*');
  return new RegExp(`^${body}${anchored ? '$' : ''}`);
}

// Longest match wins; on a tie Allow wins (RFC 9309). No matching rule = allowed.
export function isDisallowed(url, rules) {
  const u = new URL(url);
  const path = u.pathname + u.search;
  let best = null;
  for (const r of rules) {
    if (!robotsRegExp(r.pattern).test(path)) continue;
    const len = r.pattern.length;
    if (!best || len > best.len || (len === best.len && r.allow)) best = { len, allow: r.allow };
  }
  return best ? !best.allow : false;
}

// Turns an explicit path or absolute URL into the site's URL form, using the
// current sitemap locs to pick the trailing slash style. Throws on a foreign host.
export function normalisePath(input, host, locs = []) {
  const origin = `https://${host}`;
  let u;
  if (/^https?:\/\//i.test(input)) {
    u = new URL(input);
    if (u.host.toLowerCase() !== host.toLowerCase()) throw new Error(`${input} is not on ${host}`);
  } else {
    u = new URL(input.startsWith('/') ? input : `/${input}`, origin);
  }
  const suffix = u.search;
  let path = u.pathname;

  if (path === '/' && !suffix) {
    const root = locs.find((l) => l === origin || l === `${origin}/`);
    return root ?? `${origin}/`;
  }

  const bare = path.length > 1 ? path.replace(/\/+$/, '') : path;
  const set = new Set(locs);
  for (const p of [bare, `${bare}/`]) {
    if (set.has(origin + p + suffix)) return origin + p + suffix;
  }

  const nonRoot = locs.filter((l) => pathOf(l) !== '/');
  const slashed = nonRoot.filter((l) => pathOf(l).endsWith('/')).length;
  const lastSegment = bare.split('/').pop();
  if (slashed > nonRoot.length / 2 && !lastSegment.includes('.')) path = `${bare}/`;
  else path = bare;
  return origin + path + suffix;
}

// Framework file route -> pattern like '/guides/foo' or '/vpp/[slug]', or null
// when the file is not a page. `file` is repo-relative, `dir` the routes dir.
export function fileRoute(file, { dir, exts = [], router }) {
  const base = dir.replace(/\/+$/, '') + '/';
  if (!file.startsWith(base)) return null;
  const parts = file.slice(base.length).split('/');
  let name = parts.pop();

  if (router === 'astro') {
    const ext = exts.filter((e) => name.endsWith(e)).sort((a, b) => b.length - a.length)[0];
    if (!ext) return null; // .ts/.js endpoints such as [postcode].json.ts
    name = name.slice(0, -ext.length);
    if (name.replace(/\[[^\]]*\]/g, '').includes('.') || parts[0] === 'api') return null;
    if ([...parts, name].some((p) => p.startsWith('_'))) return null;
    if (name !== 'index') parts.push(name);
  } else if (router === 'next-app') {
    if (!/^page\.(tsx|ts|jsx|js|mdx)$/.test(name)) return null;
    const segs = [];
    for (const p of parts) {
      if (p.startsWith('@') || p.startsWith('_')) return null;
      if (p.startsWith('(')) {
        if (/^\([^.()][^()]*\)$/.test(p)) continue; // route group
        return null; // intercepting route
      }
      segs.push(p);
    }
    if (segs[0] === 'api') return null;
    parts.splice(0, parts.length, ...segs);
  } else {
    throw new Error(`Unknown router ${router}`);
  }
  return parts.length ? `/${parts.join('/')}` : '/';
}

const routeKey = (path) => path.replace(/\/+$/, '');

function patternRegExp(pattern) {
  const segs = routeKey(pattern).split('/').slice(1);
  let src = '';
  for (const s of segs) {
    if (/^\[\[\.\.\.[^\]]+\]\]$/.test(s)) src += '(?:/[^/]+)*';
    else if (/^\[\.\.\.[^\]]+\]$/.test(s)) src += '(?:/[^/]+)+';
    else src += '/' + s.split(/(\[[^\]]+\])/).map((t) => (t.startsWith('[') ? '[^/]+' : t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))).join('');
  }
  return new RegExp(`^${src}$`);
}

export const isStaticPattern = (pattern) => !pattern.includes('[');

// Route patterns -> the sitemap's own URLs that match them.
export function expandRoutes(patterns, sitemapUrls) {
  const res = [...new Set(patterns)].map(patternRegExp);
  return sitemapUrls.filter((url) => {
    const key = routeKey(pathOf(url));
    return res.some((re) => re.test(key));
  });
}

// Patterns for one changed file, from every ROUTES rule that matches it.
export function routesForFile(file, rules, host) {
  const out = [];
  for (const rule of rules) {
    if (rule.hosts && !rule.hosts.includes(host)) continue;
    const m = file.match(rule.file);
    if (!m) continue;
    const to = typeof rule.to === 'function' ? rule.to(m) : rule.to;
    out.push(...[to].flat().filter(Boolean));
  }
  return out;
}

// Parses `git diff --name-status --no-renames` output.
export function parseNameStatus(text) {
  return text
    .split('\n')
    .map((line) => line.split('\t'))
    .filter((p) => p.length >= 2 && p[0])
    .map(([status, file]) => ({ status: status[0], file }));
}

// Changed files -> { changed, removed } URLs. A deleted file with a static
// pattern that is no longer in the sitemap is a removal candidate.
export function mapChanges(changes, sitemapUrls, { rules, host }) {
  const live = [];
  const removed = [];
  for (const { status, file } of changes) {
    for (const pattern of routesForFile(file, rules, host)) {
      live.push(pattern);
      if (status === 'D' && isStaticPattern(pattern) && !expandRoutes([pattern], sitemapUrls).length) {
        removed.push(normalisePath(pattern, host, sitemapUrls));
      }
    }
  }
  return { changed: expandRoutes(live, sitemapUrls), removed: [...new Set(removed)] };
}

// Union of diffs; a URL keeps only its first group in added, changed, removed.
export function unionDiffs(...diffs) {
  const seen = new Set();
  const out = { added: [], changed: [], removed: [] };
  for (const group of ['added', 'changed', 'removed']) {
    for (const d of diffs) {
      for (const url of d[group] ?? []) {
        if (seen.has(url)) continue;
        seen.add(url);
        out[group].push(url);
      }
    }
  }
  return out;
}

const REPO_ROOT = dirname(dirname(fileURLToPath(import.meta.url)));

function gitChangedFiles(from, to) {
  for (const ref of [from, to]) if (!ref || ref.startsWith('-')) throw new Error(`bad ref ${ref}`);
  const out = execFileSync('git', ['diff', '--name-status', '--no-renames', from, to], {
    cwd: REPO_ROOT,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  return parseNameStatus(out);
}

// ---------- CLI ----------

function parseArgs(argv) {
  const opts = { host: HOST, key: KEY, sitemap: SITEMAP, to: 'HEAD', paths: [] };
  const valued = {
    '--host': 'host',
    '--key': 'key',
    '--sitemap': 'sitemap',
    '--prev': 'prev',
    '--out': 'out',
    '--since': 'since',
    '--from': 'from',
    '--to': 'to',
  };
  const flags = { '--dry-run': 'dryRun', '--no-check': 'noCheck', '--allow-bulk': 'allowBulk', '--help': 'help', '-h': 'help' };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--') {
      opts.paths.push(...argv.slice(i + 1));
      break;
    }
    const [name, inline] = a.startsWith('--') && a.includes('=') ? [a.slice(0, a.indexOf('=')), a.slice(a.indexOf('=') + 1)] : [a, undefined];
    if (valued[name]) {
      const v = inline ?? argv[++i];
      if (v === undefined) throw new Error(`${name} needs a value`);
      opts[valued[name]] = v;
    } else if (flags[a]) {
      opts[flags[a]] = true;
    } else if (a.startsWith('-')) {
      throw new Error(`Unknown option ${a}`);
    } else {
      opts.paths.push(a);
    }
  }
  return opts;
}

async function fetchSitemapUrls(sitemapUrl, host, seen = new Set(), depth = 0) {
  if (seen.has(sitemapUrl) || depth > 3) return {};
  seen.add(sitemapUrl);
  const fetchUrl = new URL(sitemapUrl);
  fetchUrl.searchParams.set('indexnow', String(Date.now()));
  const res = await fetch(fetchUrl, {
    headers: { 'Cache-Control': 'no-cache', 'User-Agent': `IndexNow-deploy-ping/1.0 (+https://${host}/)` },
    signal: AbortSignal.timeout(30000),
  });
  if (!res.ok) throw new Error(`${sitemapUrl}: HTTP ${res.status}`);
  const { sitemaps, urls } = parseSitemap(await res.text(), host);
  const all = { ...urls };
  for (const child of sitemaps) Object.assign(all, await fetchSitemapUrls(child, host, seen, depth + 1));
  return all;
}

async function mapLimit(items, limit, fn) {
  const out = new Array(items.length);
  let next = 0;
  const worker = async () => {
    while (next < items.length) {
      const i = next++;
      out[i] = await fn(items[i]);
    }
  };
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return out;
}

// Returns null when the URL should be kept, or a reason string to drop it:
// not a 200, noindex, or a rel=canonical pointing at a different URL.
async function checkUrl(url, kind, host) {
  let res;
  try {
    res = await fetch(url, {
      redirect: 'manual',
      headers: { 'User-Agent': `IndexNow-deploy-ping/1.0 (+https://${host}/)` },
      signal: AbortSignal.timeout(CHECK_TIMEOUT_MS),
    });
  } catch (err) {
    return `request failed (${err.message})`;
  }
  if (kind === 'removed') {
    await res.body?.cancel();
    if (res.status === 404 || res.status === 410) return null;
    const loc = res.headers.get('location');
    return `still returns HTTP ${res.status}${loc ? ` -> ${loc}` : ''}`;
  }
  if (res.status !== 200) {
    await res.body?.cancel();
    const loc = res.headers.get('location');
    return `HTTP ${res.status}${loc ? ` -> ${loc}` : ''}`;
  }
  const type = res.headers.get('content-type') ?? '';
  const html = type.includes('html') ? await res.text() : (await res.body?.cancel(), '');
  if (isNoindex(res.headers.get('x-robots-tag'), html)) return 'noindex';
  const canonical = canonicalOf(res.headers.get('link'), html, url);
  if (canonical && !sameUrl(canonical, url)) return `non-canonical -> ${canonical}`;
  return null;
}

// Rules for user-agent * from https://{host}/robots.txt. A 4xx means no rules;
// a 5xx or network error returns null and the caller sends nothing.
async function fetchRobots(host) {
  const url = `https://${host}/robots.txt`;
  try {
    const res = await fetch(url, {
      headers: { 'User-Agent': `IndexNow-deploy-ping/1.0 (+https://${host}/)` },
      signal: AbortSignal.timeout(CHECK_TIMEOUT_MS),
    });
    if (res.status >= 400 && res.status < 500) {
      await res.body?.cancel();
      console.log(`${url}: HTTP ${res.status}, no robots rules.`);
      return [];
    }
    if (!res.ok) {
      await res.body?.cancel();
      console.error(`${url}: HTTP ${res.status}.`);
      return null;
    }
    const rules = parseRobots(await res.text());
    console.log(`${url}: ${rules.length} rules for user-agent *.`);
    return rules;
  } catch (err) {
    console.error(`${url}: request failed (${err.message}).`);
    return null;
  }
}

async function loadPrev(file, host) {
  if (!file) return null;
  let snap;
  try {
    snap = JSON.parse(await readFile(file, 'utf8'));
  } catch (err) {
    console.log(err.code === 'ENOENT' ? `No previous snapshot at ${file}.` : `Ignoring unreadable snapshot ${file}: ${err.message}`);
    return null;
  }
  if (!snap || typeof snap.urls !== 'object' || snap.urls === null) {
    console.log(`Ignoring snapshot ${file}: no urls map.`);
    return null;
  }
  if (snap.host !== host) {
    console.log(`Ignoring snapshot ${file}: host is ${snap.host}, expected ${host}.`);
    return null;
  }
  return snap;
}

async function writeSnapshot(file, opts, urls) {
  if (!file) return;
  await mkdir(dirname(file), { recursive: true });
  const snap = { host: opts.host, sitemap: opts.sitemap, fetchedAt: new Date().toISOString(), urls };
  await writeFile(file, JSON.stringify(snap, null, 2) + '\n');
  console.log(`Wrote snapshot (${Object.keys(urls).length} URLs) to ${file}.`);
}

async function submit(opts, urlList) {
  const keyLocation = `https://${opts.host}/${opts.key}.txt`;
  let ok = true;
  for (let i = 0; i < urlList.length; i += BATCH_SIZE) {
    const batch = urlList.slice(i, i + BATCH_SIZE);
    try {
      const res = await fetch(ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json; charset=utf-8' },
        body: JSON.stringify({ host: opts.host, key: opts.key, keyLocation, urlList: batch }),
        signal: AbortSignal.timeout(30000),
      });
      console.log(`IndexNow HTTP ${res.status}`);
      // 200 = accepted, 202 = accepted, key validation pending.
      if (res.status !== 200 && res.status !== 202) {
        console.error((await res.text()).slice(0, 500));
        ok = false;
      }
    } catch (err) {
      console.error(`IndexNow request failed: ${err.message}`);
      ok = false;
    }
  }
  return ok;
}

export async function main(argv) {
  let opts;
  try {
    opts = parseArgs(argv);
  } catch (err) {
    console.error(`${err.message}\n\n${USAGE}`);
    return 1;
  }
  if (opts.help) {
    console.log(USAGE);
    return 0;
  }

  const explicit = opts.paths.length > 0;
  let curr = null;
  try {
    curr = await fetchSitemapUrls(opts.sitemap, opts.host);
    if (!Object.keys(curr).length) throw new Error(`no URLs for ${opts.host}`);
  } catch (err) {
    console.error(`Could not read sitemap ${opts.sitemap}: ${err.message}`);
    if (!explicit) return 1;
    console.error('Continuing with explicit paths, trailing slash style not inferred.');
    curr = null;
  }
  if (curr) {
    console.log(`${Object.keys(curr).length} URLs in ${opts.sitemap}`);
    await writeSnapshot(opts.out, opts, curr);
  }

  // groups: [label, kind, urls]
  let groups;
  if (explicit) {
    const locs = curr ? Object.keys(curr) : [];
    const urls = [];
    for (const p of opts.paths) {
      try {
        urls.push(normalisePath(p, opts.host, locs));
      } catch (err) {
        console.error(`Skipping ${p}: ${err.message}`);
      }
    }
    groups = [['explicit', 'live', [...new Set(urls)]]];
  } else {
    const prev = await loadPrev(opts.prev, opts.host);
    let siteDiff = { added: [], changed: [], removed: [] };
    if (prev) {
      siteDiff = diffSnapshots(prev.urls, curr, IGNORE_LASTMOD);
    } else if (opts.since) {
      if (Number.isNaN(Date.parse(opts.since))) {
        console.error(`Invalid --since ${opts.since}`);
        return 1;
      }
      console.log(`Comparing lastmod against --since ${opts.since}.`);
      siteDiff = { added: [], changed: changedSince(curr, opts.since, IGNORE_LASTMOD), removed: [] };
    } else if (!opts.from) {
      console.log('No previous snapshot and no --since, nothing to compare, sending nothing.');
      return 0;
    }
    console.log(`Sitemap diff: ${siteDiff.added.length}/${siteDiff.changed.length}/${siteDiff.removed.length} (added/changed/removed).`);

    let gitDiff = { changed: [], removed: [] };
    if (opts.from) {
      try {
        const files = gitChangedFiles(opts.from, opts.to);
        gitDiff = mapChanges(files, Object.keys(curr), { rules: ROUTES, host: opts.host });
        const n = gitDiff.changed.length + gitDiff.removed.length;
        console.log(`Commit range ${opts.from.slice(0, 7)}..${opts.to.slice(0, 7)}: ${files.length} files, ${n} URLs.`);
      } catch (err) {
        const msg = (err.stderr?.toString() || err.message).trim().split('\n')[0];
        console.log(`Commit range unavailable: ${msg}`);
      }
    }

    const diff = unionDiffs(siteDiff, gitDiff);
    const total = diff.added.length + diff.changed.length + diff.removed.length;
    console.log(`Union: ${diff.added.length} added, ${diff.changed.length} changed, ${diff.removed.length} removed.`);
    if (!opts.allowBulk && bulkGuard(total, Object.keys(curr).length)) {
      console.warn(
        `WARNING: ${total} of ${Object.keys(curr).length} URLs changed. This looks like a whole-site change ` +
          '(for example a template or lastmod stamp change), so nothing was sent. Re-run with --allow-bulk to send anyway.',
      );
      return 0;
    }
    groups = [
      ['added', 'live', diff.added],
      ['changed', 'live', diff.changed],
      ['removed', 'removed', diff.removed],
    ];
  }

  // robots.txt applies to every list, explicit paths included, even with --no-check.
  const robots = await fetchRobots(opts.host);
  if (robots === null) {
    console.error('Could not read robots.txt, sending nothing.');
    return 1;
  }
  for (const g of groups) {
    g[2] = g[2].filter((u) => {
      if (!isDisallowed(u, robots)) return true;
      console.log(`Dropped ${u}: robots.txt disallow`);
      return false;
    });
  }

  if (!opts.noCheck) {
    for (const g of groups) {
      const reasons = await mapLimit(g[2], CHECK_CONCURRENCY, (u) => checkUrl(u, g[1], opts.host));
      g[2] = g[2].filter((u, i) => {
        if (reasons[i]) console.log(`Dropped ${u}: ${reasons[i]}`);
        return !reasons[i];
      });
    }
  }

  const urlList = groups.flatMap((g) => g[2]);
  if (!urlList.length) {
    console.log('No changed URLs in this deploy, skipping.');
    return 0;
  }

  console.log(`${urlList.length} URLs to send:`);
  for (const [label, , urls] of groups) {
    if (!urls.length) continue;
    console.log(`  ${label}:`);
    for (const u of urls) console.log(`    ${u}`);
  }

  if (opts.dryRun) {
    console.log('Dry run, nothing sent.');
    return 0;
  }
  return (await submit(opts, urlList)) ? 0 : 1;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exitCode = await main(process.argv.slice(2));
}
